package cn.binbin.crm;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.function.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class CommerceService {
    public record ProductInput(@NotBlank @Pattern(regexp="[A-Za-z0-9_.-]{1,40}") String sku,@NotBlank @Size(max=120) String name,@NotNull @Pattern(regexp="PRODUCT|SERVICE") String kind,@NotBlank @Size(max=20) String unit,@NotNull @Min(0) @Max(100000000000L) Long priceCents,@Size(max=1000) String description,@NotNull @Pattern(regexp="ACTIVE|INACTIVE") String status,@Min(0) long expectedVersion){}
    public record LineInput(UUID id,@NotNull UUID productId,@NotNull @DecimalMin(value="0",inclusive=false) @DecimalMax("1000000") @Digits(integer=7,fraction=4) BigDecimal quantity,@Min(0) @Max(100000000000L) Long unitPriceCents,@Min(0) @Max(10000) int discountBps,@Size(max=300) String description){}
    public record QuoteInput(@NotNull UUID customerId,UUID opportunityId,@NotBlank @Size(max=200) String title,@NotNull LocalDate validUntil,@Size(max=4000) String notes,@NotEmpty @Size(max=100) List<@Valid LineInput> lines,@Min(0) long expectedVersion){}
    public record Transition(@Min(0) long expectedVersion,@Size(max=500) String reason,UUID approverMemberId){}
    public record Decision(@NotNull UUID approvalId,@Min(0) long expectedVersion,@Size(max=500) String reason){}
    private record Target(UUID id,Object input){}
    private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final AuthService auth;private final CustomerService customers;private final SalesService sales;private final ObjectMapper json;private final QuotePdf pdf;
    public CommerceService(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth,CustomerService customers,SalesService sales,ObjectMapper json,QuotePdf pdf){this.db=db;this.tx=tx;this.auth=auth;this.customers=customers;this.sales=sales;this.json=json;this.pdf=pdf;}
    private static Map<String,Object> map(Object... values){return SaasService.parameters(values);}
    private String jsonBody(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    private static String text(String value){String s=value==null?"":value.strip();if(s.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\t'))throw ApiError.bad("文本包含不支持的控制字符");return s;}
    private <T>T scoped(AuthService.Session s,String module,boolean write,Function<AuthService.Actor,T> fn){return tx.execute(status->{
        if(write&&s.tenantId()!=null)db.queryForObject("SELECT id FROM sys_tenant WHERE id=:id FOR UPDATE",Map.of("id",s.tenantId()),UUID.class);
        var a=auth.actor(s);var p=a.commerceAccess();if(a.supportGrantId()!=null)throw ApiError.forbidden("当前支持授权不包含产品和报价");
        boolean allowed=module.equals("product")?p.productRead()&&(!write||p.productWrite()):p.quotes().read()&&a.canReadCustomers()&&(!write||(module.equals("approval")?p.approve()&&a.tenant().roles().contains("SALES_MANAGER"):p.quotes().write()&&a.canWriteCustomers()))&&(!module.equals("pdf")||p.pdfExport());
        if(!allowed)throw ApiError.forbidden("当前角色没有此项产品 / 报价权限");if(write&&!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅已到期，当前仅允许查看");
        db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",Map.of("tenant",a.tenant().id().toString()),String.class);return fn.apply(a);
    });}
    Map<String,Object> params(AuthService.Actor a){var p=sales.params(a);var q=a.commerceAccess().quotes();p.put("quoteReadAll",q.readAll());p.put("quoteReadDepartment",q.readDepartment());p.put("quoteWriteAll",q.writeAll());p.put("quoteWriteDepartment",q.writeDepartment());p.put("quoteWriter",q.write()&&a.canWriteCustomers()&&a.tenant().subscriptionEnd().isAfter(Instant.now()));p.put("actorUser",a.session().userId());p.put("today",LocalDate.now(ZoneId.of("Asia/Shanghai")));p.put("approvalWriter",a.commerceAccess().approve()&&a.tenant().roles().contains("SALES_MANAGER")&&a.tenant().subscriptionEnd().isAfter(Instant.now()));return p;}
    private static String own(boolean write){return "(:quote"+(write?"Write":"Read")+"All OR q.owner_member_id=:member OR (:quote"+(write?"Write":"Read")+"Department AND m.department_id=:department))";}
    static final String FROM=" FROM crm_quote q JOIN crm_customer c ON c.tenant_id=q.tenant_id AND c.id=q.customer_id JOIN sys_tenant_member m ON m.tenant_id=q.tenant_id AND m.id=q.owner_member_id LEFT JOIN crm_opportunity o ON o.tenant_id=q.tenant_id AND o.id=q.opportunity_id ";
    static final String READ="q.tenant_id=:tenant AND "+CustomerService.READ+" AND "+own(false)+" AND (q.opportunity_id IS NULL OR ("+SalesService.OP_READ+"))";
    private static final String WRITE="(:quoteWriter AND "+CustomerService.WRITE+" AND "+own(true)+" AND (q.opportunity_id IS NULL OR "+SalesService.OP_WRITE+"))";
    private static final String APPROVE="(:approvalWriter AND q.valid_until>=:today AND EXISTS(SELECT 1 FROM crm_quote_approval ap WHERE ap.tenant_id=q.tenant_id AND ap.quote_id=q.id AND ap.status='PENDING' AND ap.submitted_version=q.version AND ap.approver_member_id=:member AND ap.submitted_user_id<>:actorUser) AND m.user_id<>:actorUser AND q.status='SUBMITTED')";
    private static final String SELECT="SELECT q.*,c.customer_name AS current_customer_name,("+WRITE+") AS can_manage,(q.status IN('DRAFT','REJECTED') AND "+WRITE+") AS can_write,("+APPROVE+") AS can_approve"+FROM;
    private List<Map<String,Object>> rows(String sql,Map<String,?> p){return db.queryForList(sql,p).stream().map(r->{var v=SaasService.view(r);v.replaceAll((k,x)->x instanceof java.sql.Date d?d.toLocalDate():x);return v;}).toList();}
    private Map<String,Object> one(String sql,Map<String,?> p){var values=rows(sql,p);if(values.isEmpty())throw ApiError.missing();return values.getFirst();}
    private void paging(int page,int size,String q){if(page<1||page>100000||size<1||size>100||q.length()>100)throw ApiError.bad("分页或搜索条件无效");}
    private Map<String,Object> product(AuthService.Actor a,UUID id){return one("SELECT * FROM crm_product WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));}
    public Object products(AuthService.Session s,int page,int size,String q,String status){paging(page,size,q);if(!Set.of("","ACTIVE","INACTIVE").contains(status))throw ApiError.bad("产品状态无效");return scoped(s,"product",false,a->{var p=map("tenant",a.tenant().id(),"q",text(q).toLowerCase(Locale.ROOT),"state",status,"limit",size,"offset",((long)page-1)*size);String where="tenant_id=:tenant AND (:state='' OR status=:state) AND (:q='' OR strpos(lower(name),:q)>0 OR strpos(lower(sku),:q)>0)";return new BusinessService.Page<>(rows("SELECT * FROM crm_product WHERE "+where+" ORDER BY updated_at DESC,id LIMIT :limit OFFSET :offset",p),page,size,db.queryForObject("SELECT count(*) FROM crm_product WHERE "+where,p,Long.class));});}
    public Object product(AuthService.Session s,UUID id){return scoped(s,"product",false,a->product(a,id));}
    private Map<String,Object> productParams(AuthService.Actor a,UUID id,ProductInput i){return map("tenant",a.tenant().id(),"id",id,"sku",text(i.sku()).toUpperCase(Locale.ROOT),"name",text(i.name()),"kind",i.kind(),"unit",text(i.unit()),"price",i.priceCents(),"description",text(i.description()),"state",i.status(),"version",i.expectedVersion());}
    public Object createProduct(AuthService.Session s,ProductInput input,String key,UUID trace){return scoped(s,"product",true,a->{UUID id=once(a,"product.create",key,input,()->{UUID created=UUID.randomUUID();db.update("INSERT INTO crm_product(id,tenant_id,sku,name,kind,unit,price_cents,description,status) VALUES(:id,:tenant,:sku,:name,:kind,:unit,:price,:description,:state)",productParams(a,created,input));audit(a,"PRODUCT_CREATED","PRODUCT",created,0,trace);return created;});return product(a,id);});}
    public Object editProduct(AuthService.Session s,UUID id,ProductInput input,UUID trace){return scoped(s,"product",true,a->{product(a,id);int count=db.update("UPDATE crm_product SET sku=:sku,name=:name,kind=:kind,unit=:unit,price_cents=:price,description=:description,status=:state,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",productParams(a,id,input));if(count!=1)throw ApiError.conflict("产品已变化，请刷新");audit(a,"PRODUCT_UPDATED","PRODUCT",id,input.expectedVersion()+1,trace);return product(a,id);});}
    private Map<String,Object> quote(AuthService.Actor a,UUID id){var p=params(a);p.put("id",id);var q=one(SELECT+"WHERE "+READ+" AND q.id=:id",p);q.put("lines",rows("SELECT * FROM crm_quote_line WHERE tenant_id=:tenant AND quote_id=:id ORDER BY line_number",p));q.put("expired",((LocalDate)q.get("validUntil")).isBefore(LocalDate.now(ZoneId.of("Asia/Shanghai"))));q.put("canPdfExport",a.commerceAccess().pdfExport());q.put("contractLinked",db.queryForObject("SELECT count(*) FROM crm_contract_quote_link l JOIN crm_contract k ON k.tenant_id=l.tenant_id AND k.id=l.contract_id WHERE l.tenant_id=:tenant AND l.quote_id=:id AND k.status<>'VOID'",p,Integer.class)>0);var approvals=rows(APPROVAL_SELECT+" WHERE tenant_id=:tenant AND quote_id=:id ORDER BY submitted_version DESC LIMIT 1",p);q.put("approval",approvals.isEmpty()?null:approvals.getFirst());return q;}
    public Object quote(AuthService.Session s,UUID id){return scoped(s,"quote",false,a->quote(a,id));}
    public Object quotes(AuthService.Session s,int page,int size,String q,String state,UUID customer,boolean mine){paging(page,size,q);if(!Set.of("","DRAFT","SUBMITTED","APPROVED","REJECTED","VOID").contains(state))throw ApiError.bad("报价状态无效");return scoped(s,"quote",false,a->{if(customer!=null)customers.get(a,customer);var p=params(a);p.put("q",text(q).toLowerCase(Locale.ROOT));p.put("state",state);p.put("customer",customer);p.put("limit",size);p.put("offset",((long)page-1)*size);p.put("mine",mine);String where=READ+" AND (NOT :mine OR "+APPROVE+") AND (:state='' OR q.status=:state) AND (cast(:customer AS uuid) IS NULL OR q.customer_id=:customer) AND (:q='' OR strpos(lower(q.title),:q)>0 OR strpos(lower(q.quote_number),:q)>0 OR strpos(lower(q.customer_name_snapshot),:q)>0)";return new BusinessService.Page<>(rows(SELECT+"WHERE "+where+" ORDER BY q.updated_at DESC,q.id LIMIT :limit OFFSET :offset",p),page,size,db.queryForObject("SELECT count(*)"+FROM+"WHERE "+where,p,Long.class));});}
    @SuppressWarnings("unchecked")
    private List<Map<String,Object>> lines(AuthService.Actor a,QuoteInput input,Map<String,Object> previous){
        if(!a.commerceAccess().productRead())throw ApiError.forbidden("编辑报价需要读取产品目录权限");if(input.validUntil().isBefore(LocalDate.of(2000,1,1))||input.validUntil().isAfter(LocalDate.of(2100,12,31)))throw ApiError.bad("有效期需在2000至2100年之间");
        var old=new HashMap<UUID,Map<String,Object>>();if(previous!=null)for(var line:(List<Map<String,Object>>)previous.get("lines"))old.put((UUID)line.get("id"),line);
        var used=new HashSet<UUID>();var result=new ArrayList<Map<String,Object>>();int number=0;long total=0;
        for(var line:input.lines()){
            Map<String,Object> source;if(line.id()!=null){source=old.get(line.id());if(source==null||!line.productId().equals(source.get("productId"))||!used.add(line.id()))throw ApiError.bad("报价行引用无效，请刷新");}
            else{source=product(a,line.productId());if(!"ACTIVE".equals(source.get("status")))throw ApiError.conflict("停用产品不能加入新的报价行");}
            long price=line.unitPriceCents()!=null?line.unitPriceCents():((Number)source.get(line.id()==null?"priceCents":"unitPriceCents")).longValue();long amount=QuoteAmounts.line(line.quantity(),price,line.discountBps());total=QuoteAmounts.add(total,amount);
            result.add(map("id",line.id()==null?UUID.randomUUID():line.id(),"product",line.productId(),"number",++number,"sku",source.get(line.id()==null?"sku":"skuSnapshot"),"name",source.get(line.id()==null?"name":"nameSnapshot"),"unit",source.get(line.id()==null?"unit":"unitSnapshot"),"quantity",line.quantity(),"price",price,"discount",line.discountBps(),"amount",amount,"description",text(line.description())));
        }return result;
    }
    private long total(List<Map<String,Object>> lines){long total=0;for(var l:lines)total=QuoteAmounts.add(total,((Number)l.get("amount")).longValue());return total;}
    private void writeLines(AuthService.Actor a,UUID id,List<Map<String,Object>> lines){db.update("DELETE FROM crm_quote_line WHERE tenant_id=:tenant AND quote_id=:id",map("tenant",a.tenant().id(),"id",id));for(var line:lines){line.put("tenant",a.tenant().id());line.put("quote",id);db.update("INSERT INTO crm_quote_line(id,tenant_id,quote_id,line_number,product_id,sku_snapshot,name_snapshot,unit_snapshot,quantity,unit_price_cents,discount_bps,amount_cents,description) VALUES(:id,:tenant,:quote,:number,:product,:sku,:name,:unit,:quantity,:price,:discount,:amount,:description)",line);}}
    private Map<String,Object> links(AuthService.Actor a,QuoteInput input){var c=customers.get(a,input.customerId());if(!c.canWrite())throw ApiError.forbidden("无权为该客户创建或编辑报价");Map<String,Object> o=null;if(input.opportunityId()!=null){if(!a.businessAccess().opportunities().read())throw ApiError.forbidden("没有关联商机权限");o=sales.opportunity(a,input.opportunityId());if(!input.customerId().equals(o.get("customerId")))throw ApiError.bad("商机不属于所选客户");if(!Boolean.TRUE.equals(o.get("canLink")))throw ApiError.forbidden("无权关联该商机");}return map("customerName",c.name(),"opTitle",o==null?null:o.get("title"));}
    public Object createQuote(AuthService.Session s,QuoteInput input,String key,UUID trace){return scoped(s,"quote",true,a->{UUID id=once(a,"quote.create",key,input,()->{if(input.lines().stream().anyMatch(l->l.id()!=null))throw ApiError.bad("新报价不能携带历史行编号");var link=links(a,input);var ls=lines(a,input,null);UUID created=UUID.randomUUID();int year=LocalDate.now(ZoneId.of("Asia/Shanghai")).getYear();var p=params(a);p.putAll(link);p.put("year",year);long sequence=db.queryForObject("INSERT INTO crm_quote_counter(tenant_id,quote_year,next_value) VALUES(:tenant,:year,1) ON CONFLICT(tenant_id,quote_year) DO UPDATE SET next_value=crm_quote_counter.next_value+1 RETURNING next_value",p,Long.class);p.putAll(map("id",created,"number",P4Numbering.format(db,a.tenant().id(),"QUOTE",year,sequence,"QT"),"title",text(input.title()),"customer",input.customerId(),"opportunity",input.opportunityId(),"company",a.tenant().name(),"ownerName",a.tenant().memberName(),"until",input.validUntil(),"notes",text(input.notes()),"total",total(ls)));
            db.update("INSERT INTO crm_quote(id,tenant_id,quote_number,title,customer_id,opportunity_id,owner_member_id,company_name_snapshot,customer_name_snapshot,opportunity_title_snapshot,owner_name_snapshot,valid_until,notes,total_cents) VALUES(:id,:tenant,:number,:title,:customer,:opportunity,:member,:company,:customerName,:opTitle,:ownerName,:until,:notes,:total)",p);writeLines(a,created,ls);revision(a,created,"CREATED",trace);return created;});return quote(a,id);});}
    public Object editQuote(AuthService.Session s,UUID id,QuoteInput input,UUID trace){return scoped(s,"quote",true,a->{var old=quote(a,id);if(!Boolean.TRUE.equals(old.get("canWrite")))throw ApiError.forbidden("当前报价无草稿编辑权限");if(!input.customerId().equals(old.get("customerId"))||!Objects.equals(input.opportunityId(),old.get("opportunityId")))throw ApiError.bad("已创建报价不能更换客户或商机，请新建报价");var ls=lines(a,input,old);var p=map("tenant",a.tenant().id(),"id",id,"version",input.expectedVersion(),"title",text(input.title()),"until",input.validUntil(),"notes",text(input.notes()),"total",total(ls));int changed=db.update("UPDATE crm_quote SET status='DRAFT',submitted_at=NULL,title=:title,valid_until=:until,notes=:notes,total_cents=:total,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status IN('DRAFT','REJECTED')",p);if(changed!=1)throw ApiError.conflict("报价已变化，请刷新后保存");writeLines(a,id,ls);revision(a,id,"UPDATED",trace);return quote(a,id);});}
    public Object transition(AuthService.Session s,UUID id,String action,Transition input,String key,UUID trace){if(!Set.of("submit","withdraw","void","revise").contains(action))throw ApiError.bad("报价动作无效");return scoped(s,"quote",true,a->{UUID selected=once(a,"quote."+action,key,new Target(id,input),()->{
        var old=quote(a,id);if(!Boolean.TRUE.equals(old.get("canManage")))throw ApiError.forbidden("无权处理该报价");if(Set.of("revise","void").contains(action)&&Boolean.TRUE.equals(old.get("contractLinked")))throw ApiError.conflict("报价已用于合同，保留原依据；金额变更请创建新的报价并审批");String state=(String)old.get("status"),next;UUID approver=null;String approverName=null;
        switch(action){case "submit"->{if(!Set.of("DRAFT","REJECTED").contains(state))throw ApiError.conflict("只有草稿或驳回报价可提交");if((boolean)old.get("expired")||((Number)old.get("totalCents")).longValue()<=0)throw ApiError.bad("提交需要有效日期和大于零的报价金额");if(input.approverMemberId()==null)throw ApiError.bad("请选择一位有权限的销售经理审批");var candidate=eligible(a,old,input.approverMemberId());approver=(UUID)candidate.get("id");approverName=(String)candidate.get("name");next="SUBMITTED";}
        case "withdraw"->{if(!state.equals("SUBMITTED"))throw ApiError.conflict("只有待审批报价可撤回");next="DRAFT";}
        case "revise"->{if(!state.equals("APPROVED"))throw ApiError.conflict("只有已批准报价需要转回草稿");if(text(input.reason()).isEmpty())throw ApiError.bad("请填写重新修改原因");next="DRAFT";}
        default->{if(state.equals("VOID"))throw ApiError.conflict("报价已经作废");if(text(input.reason()).isEmpty())throw ApiError.bad("请填写作废原因");next="VOID";}}
        int changed=db.update("UPDATE crm_quote SET status=:next,submitted_at=CASE WHEN :next='SUBMITTED' THEN now() WHEN :next='DRAFT' THEN NULL ELSE submitted_at END,voided_at=CASE WHEN :next='VOID' THEN now() ELSE NULL END,void_reason=CASE WHEN :next='VOID' THEN :reason ELSE NULL END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",map("tenant",a.tenant().id(),"id",id,"version",input.expectedVersion(),"next",next,"reason",text(input.reason())));if(changed!=1)throw ApiError.conflict("报价已变化，请刷新");
        revision(a,id,action.toUpperCase(Locale.ROOT),trace);long version=input.expectedVersion()+1;
        if(action.equals("submit")){
            String body=(String)one("SELECT snapshot::text AS body FROM crm_quote_revision WHERE tenant_id=:tenant AND quote_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",version)).get("body");UUID approval=UUID.randomUUID();var configured=rows("SELECT name,minimum_amount_cents,approver_role,self_approval,active,version FROM crm_approval_rule WHERE tenant_id=:tenant AND process_type='QUOTE' AND active",map("tenant",a.tenant().id()));Map<String,Object> rule=configured.isEmpty()?map("name","报价一级审批","minimumAmountCents",0,"approverRole","SALES_MANAGER","selfApproval",false,"active",true,"version",0):configured.getFirst();rule.put("currentAccessRequired",true);rule.put("amountMatched",((Number)old.get("totalCents")).longValue()>=((Number)rule.get("minimumAmountCents")).longValue());
            db.update("INSERT INTO crm_quote_approval(id,tenant_id,quote_id,submitted_version,submitted_member_id,submitted_user_id,approver_member_id,submitted_name_snapshot,approver_name_snapshot,amount_cents,valid_until,quote_snapshot,snapshot_sha256,rule_snapshot) VALUES(:approval,:tenant,:id,:version,:member,:user,:approver,:name,:approverName,:amount,:until,cast(:body AS jsonb),:sha,cast(:rule AS jsonb))",map("approval",approval,"tenant",a.tenant().id(),"id",id,"version",version,"member",a.tenant().memberId(),"user",a.session().userId(),"approver",approver,"name",a.tenant().memberName(),"approverName",approverName,"amount",old.get("totalCents"),"until",old.get("validUntil"),"body",body,"sha",Crypto.hash(body),"rule",jsonBody(rule)));
            approvalEvent(a,approval,id,version,"SUBMITTED","",trace);
        }else if(state.equals("SUBMITTED")){var pending=rows(APPROVAL_SELECT+" WHERE tenant_id=:tenant AND quote_id=:id AND status='PENDING'",map("tenant",a.tenant().id(),"id",id));if(!pending.isEmpty())closeApproval(a,(UUID)pending.getFirst().get("id"),id,version,action.equals("withdraw")?"WITHDRAWN":"VOID",text(input.reason()),trace);}
        return id;});return quote(a,selected);});}
    private static final String APPROVAL_SELECT="SELECT id,quote_id,submitted_version,submitted_member_id,approver_member_id,submitted_name_snapshot,approver_name_snapshot,amount_cents,valid_until,snapshot_sha256,status,created_at,decided_at,decided_member_id,decision_version,reason FROM crm_quote_approval";
    private AuthService.Actor candidateActor(AuthService.Actor a,Map<String,Object> member){
        UUID memberId=(UUID)member.get("id");var policies=db.queryForList("SELECT p.* FROM sys_role_policy p JOIN sys_member_role r ON r.tenant_id=p.tenant_id AND r.role_code=p.role_code WHERE r.tenant_id=:tenant AND r.member_id=:member",map("tenant",a.tenant().id(),"member",memberId));Set<String> roles=new HashSet<>();for(var policy:policies)roles.add((String)policy.get("role_code"));
        var tenant=new AuthService.Tenant(a.tenant().id(),a.tenant().code(),a.tenant().name(),a.tenant().status(),a.tenant().subscriptionEnd(),memberId,(String)member.get("display_name"),roles);
        var customer=CustomerAccess.from(policies);return new AuthService.Actor(a.session(),tenant,customer,(UUID)member.get("department_id"),null,BusinessAccess.from(policies,customer),DeliveryAccess.from(policies),CommerceAccess.from(policies));
    }
    private List<Map<String,Object>> eligible(AuthService.Actor a,Map<String,Object> quote){
        UUID ownerUser=db.queryForObject("SELECT user_id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",quote.get("ownerMemberId")),UUID.class);
        var candidates=db.queryForList("SELECT m.id,m.display_name,m.department_id FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.status='ACTIVE' AND u.status='ACTIVE' AND NOT u.must_change_password AND m.user_id<>:user AND m.user_id<>:owner AND EXISTS(SELECT 1 FROM sys_member_role r JOIN sys_role_policy rp ON rp.tenant_id=r.tenant_id AND rp.role_code=r.role_code WHERE r.tenant_id=m.tenant_id AND r.member_id=m.id AND r.role_code='SALES_MANAGER' AND rp.quote_can_approve AND rp.quote_can_read) ORDER BY m.display_name,m.id",map("tenant",a.tenant().id(),"user",a.session().userId(),"owner",ownerUser));
        var result=new ArrayList<Map<String,Object>>();for(var member:candidates){var actor=candidateActor(a,member);var p=params(actor);p.put("id",quote.get("id"));if(actor.canReadCustomers()&&actor.commerceAccess().approve()&&db.queryForObject("SELECT count(*)"+FROM+"WHERE "+READ+" AND q.id=:id",p,Integer.class)==1)result.add(map("id",member.get("id"),"name",member.get("display_name")));}return result;
    }
    private Map<String,Object> eligible(AuthService.Actor a,Map<String,Object> quote,UUID id){return eligible(a,quote).stream().filter(m->id.equals(m.get("id"))).findFirst().orElseThrow(()->ApiError.bad("审批人不可用，需另一位有当前资料权限的有效销售经理"));}
    public Object approvers(AuthService.Session s,UUID id,int page,int size,String search){paging(page,size,search);return scoped(s,"quote",false,a->{var quote=quote(a,id);if(!Boolean.TRUE.equals(quote.get("canManage")))throw ApiError.forbidden("没有报价提交权限");String q=text(search).toLowerCase(Locale.ROOT);var candidates=eligible(a,quote).stream().filter(m->((String)m.get("name")).toLowerCase(Locale.ROOT).contains(q)).toList();int offset=(int)Math.min(((long)page-1)*size,candidates.size());return new BusinessService.Page<>(candidates.subList(offset,Math.min(offset+size,candidates.size())),page,size,candidates.size());});}
    public Object approvals(AuthService.Session s,UUID id,int page,int size){paging(page,size,"");return scoped(s,"quote",false,a->{quote(a,id);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(rows(APPROVAL_SELECT+" WHERE tenant_id=:tenant AND quote_id=:id ORDER BY submitted_version DESC LIMIT :limit OFFSET :offset",p),page,size,db.queryForObject("SELECT count(*) FROM crm_quote_approval WHERE tenant_id=:tenant AND quote_id=:id",p,Long.class));});}
    public Object approval(AuthService.Session s,UUID id,UUID approval){return scoped(s,"quote",false,a->{quote(a,id);var p=map("tenant",a.tenant().id(),"id",id,"approval",approval);var record=one(APPROVAL_SELECT+" WHERE tenant_id=:tenant AND quote_id=:id AND id=:approval",p);var body=one("SELECT quote_snapshot::text AS body,rule_snapshot::text AS rule FROM crm_quote_approval WHERE tenant_id=:tenant AND quote_id=:id AND id=:approval",p);try{record.put("quoteSnapshot",json.readValue((String)body.get("body"),Map.class));record.put("ruleSnapshot",json.readValue((String)body.get("rule"),Map.class));}catch(Exception e){throw new IllegalStateException(e);}record.put("events",rows("SELECT business_version,action,actor_name_snapshot,reason,created_at FROM crm_quote_approval_event WHERE tenant_id=:tenant AND quote_id=:id AND approval_id=:approval ORDER BY business_version",p));return record;});}
    private void approvalEvent(AuthService.Actor a,UUID approval,UUID quote,long version,String action,String reason,UUID trace){db.update("INSERT INTO crm_quote_approval_event(id,tenant_id,approval_id,quote_id,business_version,action,actor_member_id,actor_name_snapshot,reason) VALUES(:event,:tenant,:approval,:quote,:version,:action,:member,:name,:reason)",map("event",UUID.randomUUID(),"tenant",a.tenant().id(),"approval",approval,"quote",quote,"version",version,"action",action,"member",a.tenant().memberId(),"name",a.tenant().memberName(),"reason",reason));audit(a,"QUOTE_APPROVAL_"+action,"QUOTE_APPROVAL",approval,version,trace);}
    private void closeApproval(AuthService.Actor a,UUID approval,UUID quote,long version,String state,String reason,UUID trace){int changed=db.update("UPDATE crm_quote_approval SET status=:state,decided_at=now(),decided_member_id=:member,decision_version=:version,reason=:reason WHERE tenant_id=:tenant AND id=:approval AND quote_id=:quote AND status='PENDING'",map("tenant",a.tenant().id(),"approval",approval,"quote",quote,"version",version,"state",state,"member",a.tenant().memberId(),"reason",reason));if(changed!=1)throw ApiError.conflict("审批已处理，请刷新");approvalEvent(a,approval,quote,version,state,reason,trace);}
    public Object decide(AuthService.Session s,UUID id,String action,Decision input,String key,UUID trace){if(!Set.of("approve","reject").contains(action))throw ApiError.bad("审批动作无效");return scoped(s,"approval",true,a->{UUID selected=once(a,"quote.approval."+action,key,new Target(id,input),()->{
        var q=quote(a,id);var request=one("SELECT *,quote_snapshot::text AS body FROM crm_quote_approval WHERE tenant_id=:tenant AND id=:approval AND quote_id=:id FOR UPDATE",map("tenant",a.tenant().id(),"approval",input.approvalId(),"id",id));
        if(!a.tenant().memberId().equals(request.get("approverMemberId")))throw ApiError.forbidden("只有指定审批人可以处理");UUID ownerUser=db.queryForObject("SELECT user_id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",q.get("ownerMemberId")),UUID.class);
        if(a.session().userId().equals(request.get("submittedUserId"))||a.session().userId().equals(ownerUser))throw ApiError.forbidden("提交人和报价人不能自审");
        if(!"PENDING".equals(request.get("status"))||!"SUBMITTED".equals(q.get("status"))||((Number)q.get("version")).longValue()!=input.expectedVersion()||((Number)request.get("submittedVersion")).longValue()!=input.expectedVersion())throw ApiError.conflict("审批或报价版本已变化，请刷新");
        if((boolean)q.get("expired"))throw ApiError.bad("报价已过期，请撤回修改后重新提交");if(!Objects.equals(q.get("totalCents"),request.get("amountCents"))||!Crypto.same(Crypto.hash((String)request.get("body")),(String)request.get("snapshotSha256")))throw ApiError.conflict("报价快照校验失败");String reason=text(input.reason());if(action.equals("reject")&&reason.isEmpty())throw ApiError.bad("驳回必须填写原因");String state=action.equals("approve")?"APPROVED":"REJECTED";
        int changed=db.update("UPDATE crm_quote SET status=:state,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND status='SUBMITTED' AND version=:version",map("tenant",a.tenant().id(),"id",id,"state",state,"version",input.expectedVersion()));if(changed!=1)throw ApiError.conflict("报价已变化，请刷新");revision(a,id,state,trace);closeApproval(a,input.approvalId(),id,input.expectedVersion()+1,state,reason,trace);return id;});return quote(a,selected);});}
    private Map<String,Object> snapshot(AuthService.Actor a,UUID id){var q=quote(a,id);q.keySet().removeAll(Set.of("canWrite","canManage","canPdfExport","expired","currentCustomerName","canApprove","approval","contractLinked"));return q;}
    private void revision(AuthService.Actor a,UUID id,String action,UUID trace){var snap=snapshot(a,id);long version=((Number)snap.get("version")).longValue();String body;try{body=json.writeValueAsString(snap);}catch(Exception e){throw new IllegalStateException(e);}db.update("INSERT INTO crm_quote_revision(id,tenant_id,quote_id,business_version,action,snapshot,actor_member_id) VALUES(:revision,:tenant,:id,:version,:action,cast(:snapshot AS jsonb),:member)",map("revision",UUID.randomUUID(),"tenant",a.tenant().id(),"id",id,"version",version,"action",action,"snapshot",body,"member",a.tenant().memberId()));audit(a,"QUOTE_"+action,"QUOTE",id,version,trace);}
    public Object history(AuthService.Session s,UUID id,int page,int size){paging(page,size,"");return scoped(s,"quote",false,a->{quote(a,id);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(rows("SELECT r.id,r.business_version,r.action,r.created_at,m.display_name AS actor_name FROM crm_quote_revision r JOIN sys_tenant_member m ON m.tenant_id=r.tenant_id AND m.id=r.actor_member_id WHERE r.tenant_id=:tenant AND r.quote_id=:id ORDER BY r.business_version DESC LIMIT :limit OFFSET :offset",p),page,size,db.queryForObject("SELECT count(*) FROM crm_quote_revision WHERE tenant_id=:tenant AND quote_id=:id",p,Long.class));});}
    private Map<String,Object> revision(AuthService.Actor a,UUID id,long version){quote(a,id);var record=one("SELECT snapshot::text AS snapshot FROM crm_quote_revision WHERE tenant_id=:tenant AND quote_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",version));try{return json.readValue((String)record.get("snapshot"),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});}catch(Exception e){throw new IllegalStateException(e);}}
    public Object revision(AuthService.Session s,UUID id,long version){if(version<0)throw ApiError.bad("报价版本无效");return scoped(s,"quote",false,a->revision(a,id,version));}
    public byte[] pdf(AuthService.Session s,UUID id,long version,UUID trace){if(version<0)throw ApiError.bad("报价版本无效");return scoped(s,"pdf",false,a->{var snap=revision(a,id,version);byte[] bytes=pdf.render(snap);audit(a,"QUOTE_PDF_EXPORTED","QUOTE",id,version,trace);return bytes;});}
    Map<String,Object> quoteForTrade(AuthService.Actor a,UUID id){if(!a.commerceAccess().quotes().read()||!a.canReadCustomers())throw ApiError.forbidden("需要报价读取权限");return quote(a,id);}
    Map<String,Object> revisionForTrade(AuthService.Actor a,UUID id,long version){quoteForTrade(a,id);return revision(a,id,version);}
    Map<String,Object> approvedForTrade(AuthService.Actor a,UUID id,long version){var q=quoteForTrade(a,id);if(((Number)q.get("version")).longValue()!=version)throw ApiError.conflict("报价版本已变化，请刷新");if(!"APPROVED".equals(q.get("status"))||(boolean)q.get("expired"))throw ApiError.conflict("需要当前有效的已批准报价");var approval=(Map<?,?>)q.get("approval");if(approval==null||!"APPROVED".equals(approval.get("status"))||((Number)approval.get("decisionVersion")).longValue()!=version||!q.get("totalCents").equals(approval.get("amountCents")))throw ApiError.conflict("批准记录与当前报价不一致");var record=one("SELECT quote_snapshot::text AS body,snapshot_sha256 FROM crm_quote_approval WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",approval.get("id")));if(!Crypto.same(Crypto.hash((String)record.get("body")),(String)record.get("snapshotSha256")))throw ApiError.conflict("批准快照完整性未通过");return q;}
    private UUID once(AuthService.Actor a,String operation,String key,Object input,Supplier<UUID> fn){if(!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号格式无效");String hash;try{hash=Crypto.hash(json.writeValueAsString(input));}catch(Exception e){throw new IllegalStateException(e);}var p=map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"op",operation,"key",key,"hash",hash);db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash) VALUES(:tenant,:member,:op,:key,:hash) ON CONFLICT DO NOTHING",p);var prior=db.queryForMap("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key FOR UPDATE",p);if(!hash.equals(prior.get("request_hash")))throw ApiError.conflict("相同请求编号对应的内容已变化");if(prior.get("result_id")!=null)return (UUID)prior.get("result_id");UUID id=fn.get();p.put("id",id);db.update("UPDATE sys_idempotency_request SET result_id=:id WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key",p);return id;}
    private void audit(AuthService.Actor a,String action,String type,UUID id,long version,UUID trace){db.update("INSERT INTO sys_audit_log(id,tenant_id,actor_member_id,action,entity_type,entity_id,business_version,trace_id) VALUES(:id,:tenant,:member,:action,:type,:entity,:version,:trace)",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"member",a.tenant().memberId(),"action",action,"type",type,"entity",id,"version",version,"trace",trace));}
}
